def backfill_envelopes(apps, schema_editor):
    """Copy each request's project (directly or through its part) to its intake envelope (row-level security per tenant)."""
    from apps.tenancy.context import tenant_context

    Tenant = apps.get_model("tenancy", "Tenant")
    Request = apps.get_model("servicerequests", "ClientRequest")
    Envelope = apps.get_model("servicerequests", "RequestEnvelope")
    op = Tenant.objects.filter(kind="operator").first()
    if op is None:
        return
    projects = {}
    for t in Tenant.objects.exclude(pk=op.pk):
        with tenant_context(t.pk):
            for rid, pid, part_pid in Request.objects.values_list("pk", "project_id", "part__project_id"):
                if pid or part_pid:
                    projects[rid] = pid or part_pid
    with tenant_context(op.pk):
        for env in Envelope.objects.filter(request_id__in=list(projects)):
            env.project_ref = projects[env.request_id]
            env.save(update_fields=["project_ref"])


